-- ----------------------------------------------------------------------------
-- Parking Fury Guide — database seed (MySQL / MariaDB, e.g. Hostinger)
--
-- How to use (Hostinger hPanel):
--   1. Databases → MySQL → create a database + user, note the credentials.
--   2. phpMyAdmin → select that database → Import → choose this file → Go.
--   3. Copy those credentials into .env (DB_DSN/DB_USER/DB_PASS).
--
-- Note: the PHP app also self-creates empty tables on first request, so the
-- import step is only needed to load these 12 games in one go.
-- Generated from data/games.json — 12 games, covers must already be
-- present in /uploads/ (they ship with the project).
-- ----------------------------------------------------------------------------

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `games` (
  `id`          VARCHAR(64)  NOT NULL,
  `slug`        VARCHAR(80)  NOT NULL,
  `title`       VARCHAR(200) NOT NULL,
  `description` TEXT         NOT NULL,
  `category`    VARCHAR(60)  NOT NULL DEFAULT '',
  `tags`        TEXT         NULL,
  `controls`    TEXT         NULL,
  `specs`       TEXT         NULL,
  `cover`       VARCHAR(255) NULL,
  `embed_url`   VARCHAR(500) NOT NULL,
  `status`      VARCHAR(20)  NOT NULL DEFAULT 'draft',
  `featured`    TINYINT(1)   NOT NULL DEFAULT 0,
  `created_at`  DATETIME     NOT NULL,
  `updated_at`  DATETIME     NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY games_slug (`slug`),
  KEY games_status (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `analytics` (
  `day`    DATE        NOT NULL,
  `kind`   VARCHAR(10) NOT NULL,
  `ref`    VARCHAR(220) NOT NULL,
  `count`  INT         NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`, `kind`, `ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('seed-tight-lot','tight-lot','Parking Fury','Parking Fury is the ultimate test of driving precision and finesse. Steer through complex parking lots, navigate around obstacles, and park inside the marked bay without a scratch. Experience the classic game that started the sensation.','Parking','["parking fury","parking games","car parking","driving games","html5","browser games","classic"]','Arrow keys or WASD to accelerate, brake, reverse and steer. Tap keys lightly for fine cornering control.','[{"label":"Game Type","value":"Precision Parking"},{"label":"Genre","value":"Driving"},{"label":"Platform","value":"Web Browser"},{"label":"Technology","value":"HTML5"},{"label":"Mode","value":"Single Player"},{"label":"Input","value":"Keyboard / Touch"}]','/uploads/g-mvhs1q65-9f1503bf.jpg/','https://www.bubbleshooter.net/embed.php?id=1695','published',1,'2026-10-20 12:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('seed-traffic-rush','traffic-rush','Parking Fury 2','Parking Fury 2 expands the top-down driving experience with 10 demanding levels, new vehicle types, damaged asphalt routes, and higher difficulty curves. Park each vehicle safely into designated bays.','Parking','["parking fury 2","parking games","driving games","arcade","precision"]','WASD or Arrow Keys to steer, accelerate and reverse. Follow the yellow guide arrows.','[{"label":"Game Type","value":"Top-Down Parking"},{"label":"Genre","value":"Driving"},{"label":"Levels","value":"10 Stages"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-mvhs6r7l-f4c36f71.jpg/','https://www.bubbleshooter.net/embed.php?id=1696','published',1,'2026-10-20 12:05:00','2026-10-21 17:10:34');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-pf-3','parking-fury-3','Parking Fury 3','Take on the darkness in Parking Fury 3. Steer sports cars, sedans, and trucks through dimly lit lots using your headlights to spot barriers and marked bays in the dead of night.','Parking','["parking fury 3","night parking","headlights","driving games","hard parking"]','Arrow keys or WASD to drive. Use headlights to judge distances before turning into slots.','[{"label":"Game Type","value":"Night Parking"},{"label":"Genre","value":"Driving Simulation"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-pf3.jpg/','https://www.bubbleshooter.net/embed.php?id=1697','published',0,'2026-10-21 18:00:00','2026-10-21 16:21:58');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('72b2ccd1-28ae-4b4d-a3a1-042d7544f5a2','parking-fury-3d','Parking Fury 3D','Enter an open 3D city environment where driving is only half the mission. Steal vehicles, outsmart police patrol routes, and deliver high-value rides into tight garages across the city.','Driving','["parking fury 3d","3D driving","police chase","car theft","city driving"]','Arrow keys to drive; Ctrl to enter or exit vehicles; C to switch camera views.','[{"label":"Game Type","value":"3D Action Driving"},{"label":"Graphics","value":"Full 3D"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-mvhrth5h-4f26a042.jpg/','https://www.bubbleshooter.net/embed.php?id=1698','published',0,'2026-10-21 07:08:32','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('045113f3-0092-41e7-9f4a-ab4c90b0ae66','parking-fury-3d-beach-city','Parking Fury 3D: Beach City','Navigate sunny seaside boulevards and narrow coastal alleyways in Beach City. Evade patrolling squad cars, find hidden vehicles, and park cleanly in crowded beachside bays.','Driving','["beach city","3d parking","parking fury 3d","supercars","city exploration"]','Arrow keys to drive; Ctrl to enter cars; Space for handbrake; C to change camera.','[{"label":"Game Type","value":"3D Coastal Driving"},{"label":"Environment","value":"Beach City 3D"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-mvhsiw7n-692eea77.jpg/','https://www.bubbleshooter.net/embed.php?id=1714','published',0,'2026-10-21 07:28:18','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-pf-3d-bounty','parking-fury-3d-bounty-hunter','Parking Fury 3D: Bounty Hunter','Hunt high-value target cars in a gritty 3D metropolis. Outrun pursuing squad cars, manage sharp turns in narrow back alleys, and deliver each vehicle to safe drops for lucrative rewards.','Driving','["bounty hunter","3d racing","missions","action driving","parking fury"]','WASD or Arrow keys to steer and accelerate; Ctrl to steal car; Space handbrake; C camera.','[{"label":"Game Type","value":"Mission Driving"},{"label":"Setting","value":"Urban 3D"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-bounty.jpg/','https://www.bubbleshooter.net/embed.php?id=1716','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-pf-3d-night-thief','parking-fury-3d-night-thief','Parking Fury 3D: Night Thief','Operate under cover of darkness as an undercover car collector. Infiltrate restricted docks and city garages, commandeer luxury rides, and deliver them without triggering security alarms.','Driving','["night thief","stealth driving","3d parking","supercars","evasion"]','WASD or Arrow keys to drive; Ctrl to switch vehicles; Space to drift; C for camera.','[{"label":"Game Type","value":"3D Stealth Driving"},{"label":"Time","value":"Midnight Operations"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-nightthief.jpg/','https://www.bubbleshooter.net/embed.php?id=1715','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-extreme-parking','extreme-car-parking','Extreme Car Parking','Push your spatial judgment to the brink. Navigate razor-thin slalom barriers, tight ninety-degree bends, and micro-parking bays with zero tolerance for collision.','Parking','["extreme parking","skill challenge","precision driving","tight spaces"]','Arrow keys or touch controls to accelerate, reverse, and steer smoothly.','[{"label":"Game Type","value":"Hardcore Parking"},{"label":"Difficulty","value":"Expert"},{"label":"Platform","value":"Web Browser & Mobile"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-extremepark.jpg/','https://www.bubbleshooter.net/embed.php?id=1702','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-car-parking-school','car-parking-school','Car Parking School','Learn professional driving academy maneuvers including parallel curb docking, reverse angle parking, and navigating busy traffic training circuits in modern simulation graphics.','Parking','["driving school","parking simulator","parallel parking","tutorial driving"]','WASD or arrow keys to steer and pedal; E for camera; Space for brake.','[{"label":"Game Type","value":"Driving Academy"},{"label":"Skills","value":"Parallel & Reverse Parking"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-parkschool.jpg/','https://www.bubbleshooter.net/embed.php?id=1700','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-dubai-police-parking','dubai-police-parking-2','Dubai Police Parking 2','Get behind the wheel of million-dollar Dubai Police patrol supercars. Respond to alert zones and maneuver high-horsepower luxury interceptors into marked incident parking spots.','Driving','["dubai police","supercar parking","luxury patrol","fast cars"]','Arrow keys or WASD to accelerate and steer; Space for instant handbrake lock.','[{"label":"Game Type","value":"Supercar Patrol"},{"label":"Setting","value":"Dubai City"},{"label":"Platform","value":"Web Browser"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-dubaipolice.jpg/','https://www.bubbleshooter.net/embed.php?id=1705','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-park-out','park-out','Park Out & Master','Engage your brain with grid-based parking lot puzzle mechanics. Slide obstructing sedans, buses, and sports cars along their tracks to clear the golden exit lane for your car.','Puzzle','["traffic jam","car puzzle","logic game","sliding block","brain game"]','Mouse click/drag or touch swipe to slide vehicles forward and backward.','[{"label":"Game Type","value":"Logic Puzzle"},{"label":"Mechanic","value":"Sliding Block"},{"label":"Platform","value":"Desktop & Mobile"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-parkout.jpg/','https://www.bubbleshooter.net/embed.php?id=1709','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
INSERT INTO `games` (`id`,`slug`,`title`,`description`,`category`,`tags`,`controls`,`specs`,`cover`,`embed_url`,`status`,`featured`,`created_at`,`updated_at`) VALUES ('game-drive-and-park','drive-and-park','Drive and Park','Fast-paced one-tap drifting and parking action. Release your drift at the exact microsecond to glide into curbside spots between other parked cars at top speed.','Arcade','["drift parking","one tap","timing game","arcade driving"]','Press and hold Space / Left Mouse / Screen to initiate drift; release to straighten.','[{"label":"Game Type","value":"Arcade Timing"},{"label":"Input","value":"One-Touch / Key"},{"label":"Platform","value":"Web Browser & Mobile"},{"label":"Mode","value":"Single Player"}]','/uploads/g-cover-drivepark.jpg/','https://www.bubbleshooter.net/embed.php?id=1704','published',0,'2026-10-21 18:00:00','2026-10-21 18:00:00');
